import{_ as e,o,c as n,ah as a}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Internal edPage panel","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/admission/staff-edpage/index.md","filePath":"src/en/admission/staff-edpage/index.md"}'),s={name:"en/admission/staff-edpage/index.md"};function r(i,t,d,h,l,g){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="internal-edpage-panel" tabindex="-1">Internal edPage panel <a class="header-anchor" href="#internal-edpage-panel" aria-label="Permalink to &quot;Internal edPage panel&quot;">​</a></h1><p>The internal Era Admission panel is the tool reserved for the edPage team to manage the lifecycle of schools signed up online: granting a license, ending a demo early, or purging an expired school. It&#39;s also where the team edits Era Admission&#39;s <strong>landing page</strong> and handles the <strong>contact requests</strong> it receives. It has nothing to do with a client school&#39;s own user account — it&#39;s an entirely separate access.</p><p>The menu at the top of the panel leads to its screens: <strong>Schools</strong>, <strong>Landing page</strong>, <strong>Contact requests</strong>, <strong>Quotes</strong> and <strong>Online payment</strong> (requests to switch online payment on). On the right, <strong>View landing page</strong> opens the public page in a new tab, and <strong>Password</strong> leads to changing your own password.</p><h2 id="logging-into-the-panel" tabindex="-1">Logging into the panel <a class="header-anchor" href="#logging-into-the-panel" aria-label="Permalink to &quot;Logging into the panel&quot;">​</a></h2><ol><li>Go to the staff login page, reachable on ERA&#39;s central domain (the one hosting the signup site, not a school&#39;s subdomain).</li><li>Enter your <strong>staff account</strong> email address and password — this account is independent of any school account, it only exists for the edPage team.</li><li>Submit. You land on the schools list.</li></ol><p>The staff login form is deliberately minimal (no public signup, no two-factor authentication, no &quot;forgot password&quot;): staff accounts are created by hand, not through a public flow.</p><h2 id="changing-your-password" tabindex="-1">Changing your password <a class="header-anchor" href="#changing-your-password" aria-label="Permalink to &quot;Changing your password&quot;">​</a></h2><p>Your account is handed to you with a temporary password. Change it on first login:</p><ol><li>Click <strong>Password</strong>, at the top right of the panel.</li><li>Enter your current password, then the new one, twice.</li><li>Submit: a message confirms the change.</li></ol><p>Since this panel sends no reset email, a forgotten password cannot be recovered from the login screen: ask the server administrator to set a new one, then change it again here once you are logged in.</p><h2 id="viewing-the-schools-list" tabindex="-1">Viewing the schools list <a class="header-anchor" href="#viewing-the-schools-list" aria-label="Permalink to &quot;Viewing the schools list&quot;">​</a></h2><p>Once logged in, the &quot;Schools&quot; page lists every school that has signed up, with for each one:</p><ul><li>its name and subdomain;</li><li>its <strong>status</strong>: free, demo, licensed, or expired;</li><li>its active <strong>modules</strong> (none on free; all on demo; whichever are actually licensed on licensed; none on expired);</li><li>its <strong>hosting formula</strong> (self-hosted or managed);</li><li>the demo end date, the date maintenance is paid through, and how long the school has been expired, whichever applies.</li></ul><p>Each row then offers the actions available for that school, described below — some only appear for certain statuses.</p><h2 id="granting-a-license" tabindex="-1">Granting a license <a class="header-anchor" href="#granting-a-license" aria-label="Permalink to &quot;Granting a license&quot;">​</a></h2><p>Available for any school, regardless of its current status.</p><ol><li>On the row for the school in question, click <strong>License</strong>.</li><li>In the dialog, check the modules to grant (or the &quot;Full offer&quot; option for every module at once). Each module&#39;s price is shown next to its name.</li><li>Fill in, if needed, the date maintenance is paid through. Left blank, it defaults to one year from today.</li><li>Confirm with <strong>Grant license</strong>.</li></ol><p>The school immediately moves to &quot;Licensed&quot; status, with the checked modules active, while staying hosted on edPage&#39;s infrastructure (the &quot;Managed&quot; formula). If the school ultimately needs to host its own installation instead (the &quot;Self-hosted&quot; formula), that switch is done through a dedicated command-line tool, outside this panel — don&#39;t use this action for that case.</p><p>This action can also be used to <strong>modify</strong> the license of an already licensed school (adding a module, extending maintenance): simply apply it again with the new values.</p><h2 id="ending-a-demo-manually" tabindex="-1">Ending a demo manually <a class="header-anchor" href="#ending-a-demo-manually" aria-label="Permalink to &quot;Ending a demo manually&quot;">​</a></h2><p>Available only for a school with &quot;Demo&quot; status. The action doesn&#39;t appear on other statuses.</p><ol><li>On the school&#39;s row, click <strong>End demo</strong>.</li><li>Confirm in the dialog — the action is immediate.</li></ol><p>The school moves to &quot;Expired&quot; status and switches to read-only, exactly as if its demo had ended naturally at its scheduled deadline. Use this action to end a demo before its normal term (for example at the school&#39;s request, or in case of misuse) — it isn&#39;t needed in the ordinary course of things, since the demo ends on its own.</p><h2 id="purging-an-expired-school" tabindex="-1">Purging an expired school <a class="header-anchor" href="#purging-an-expired-school" aria-label="Permalink to &quot;Purging an expired school&quot;">​</a></h2><p>Available only for a school with &quot;Expired&quot; status. This action is <strong>final and irreversible</strong>.</p><ol><li>On the school&#39;s row, click <strong>Purge</strong>.</li><li>Read the warning message in the dialog carefully: it states that the school, its database, and its storage will be deleted immediately, with no grace period and no way to undo it.</li><li>Confirm with <strong>Delete permanently</strong>.</li></ol><p>In the ordinary course of things, a school expired for too long is purged automatically once its grace period elapses. Use this manual action only to purge a school ahead of that automatic deadline — for example at the school&#39;s explicit request to delete its data without waiting.</p><h2 id="editing-the-landing-page" tabindex="-1">Editing the landing page <a class="header-anchor" href="#editing-the-landing-page" aria-label="Permalink to &quot;Editing the landing page&quot;">​</a></h2><p>The landing page is the public page shown at Era Admission&#39;s main address (the central domain, not a school&#39;s subdomain). It presents the offer to schools and leads to the free signup or to a proposal request, and its pricing configurator lets a school build its licence and ask for a quote.</p><p>The <strong>Landing page</strong> screen starts with the page&#39;s <strong>Appearance</strong>, then the <strong>Page sections</strong> block (the order of the parts and the added sections). It then lists each part in display order, and ends with <strong>Labels</strong> and <strong>Sharing and search</strong>. The original parts are:</p><table tabindex="0"><thead><tr><th>Part</th><th>Editable content</th><th>Shown</th></tr></thead><tbody><tr><td><strong>Header</strong></td><td>Eyebrow, headline title and text</td><td>Always</td></tr><tr><td><strong>In short</strong></td><td>One card per point (four recommended)</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Levels</strong></td><td>Eyebrow, title, text, one card per pôle</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Free offer</strong></td><td>Eyebrow, title and text</td><td>If <strong>Show</strong> is ticked</td></tr><tr><td><strong>Curricula</strong></td><td>Eyebrow, title, text, one card per table row</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Modules</strong></td><td>Eyebrow, title, text, one card per module</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Higher education</strong></td><td>Eyebrow, title, text, one card per point</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>On site</strong></td><td>Eyebrow, title, text, one card per need</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Pricing &amp; quote</strong></td><td>Eyebrow, title, text, priced cards and terms</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Onboarding</strong></td><td>Eyebrow, title, text, one card per step</td><td>If <strong>Show</strong> is ticked and there is a card</td></tr><tr><td><strong>Frequently asked questions</strong></td><td>Eyebrow, title, questions and answers</td><td>If <strong>Show</strong> is ticked and there is a question</td></tr><tr><td><strong>Contact</strong></td><td>Eyebrow, title and text above the form</td><td>Always</td></tr></tbody></table><p>The page&#39;s drawings (the header&#39;s dashboard and family portal, the levels timeline, the application form, the report card, the payment tracking, the messages to families, the student path, the &quot;offline&quot; diagram) aren&#39;t editable: their texts follow the page&#39;s language, with fictitious names.</p><p>The <strong>eyebrow</strong> is the small uppercase line above a part&#39;s title (&quot;CURRICULA&quot;, &quot;CONTACT&quot;…). The contact and quote forms&#39; fields aren&#39;t editable.</p><h3 id="choosing-the-appearance" tabindex="-1">Choosing the appearance <a class="header-anchor" href="#choosing-the-appearance" aria-label="Permalink to &quot;Choosing the appearance&quot;">​</a></h3><p>The <strong>Appearance</strong> part sets the look of the whole page. Colors and logo stay ERA&#39;s: the landing page presents the product.</p><ul><li><strong>Layout of the top of the page</strong>: <strong>Illustrated</strong> (the title on the left, a drawing of the product on the right, no photo; the default layout), <strong>Centered</strong> (the title in the middle), <strong>Full screen</strong> (a photo across the full width, the text over it), <strong>Side by side</strong> (the text on the left, the photo on the right) or <strong>Editorial</strong> (a large title, then the photo as a banner). The module chips under the buttons only appear with <strong>Centered</strong>.</li><li><strong>Image at the top of the page</strong>: the header photo (PNG, JPG or WebP, 4 MB at most), with the <strong>veil</strong> that darkens it to keep the text legible and the <strong>image framing</strong> (center, top, bottom).</li><li><strong>Page background</strong>: colored glow, plain or tinted.</li><li><strong>Show the logo icon</strong> above the title (the full logo stays in the top bar).</li><li><strong>Ambiance</strong>: the <strong>fonts</strong> (<strong>Bold</strong> by default: very heavy titles), the frames&#39; <strong>corners</strong>, the <strong>buttons&#39;</strong> shape and the <strong>section backgrounds</strong>. With <strong>Solid color</strong>, onboarding moves onto the main color; the denser parts (levels, curricula, higher education, pricing) stay on a tint to remain legible.</li></ul><p>Left untouched, the page uses the <strong>Illustrated</strong> layout and the <strong>Bold</strong> font. An appearance already saved is kept: to switch to the new look, pick these two options and save.</p><h3 id="ordering-sections-and-adding-new-ones" tabindex="-1">Ordering sections and adding new ones <a class="header-anchor" href="#ordering-sections-and-adding-new-ones" aria-label="Permalink to &quot;Ordering sections and adding new ones&quot;">​</a></h3><p>The <strong>Page sections</strong> block lists every part below the header, in display order: the original ones as well as those you add. The arrows move them up or down. The header always stays at the top of the page.</p><p><strong>Add a section</strong> offers the same types as a school&#39;s homepage. The section is added at the bottom of the list, empty, with its own block in the editor, and only appears on the landing page once filled in:</p><table tabindex="0"><thead><tr><th>Section</th><th>Content</th><th>Maximum</th></tr></thead><tbody><tr><td><strong>Key figures</strong></td><td>A value (&quot;120&quot;, &quot;98%&quot;) and what it measures</td><td>8 figures</td></tr><tr><td><strong>Photo gallery</strong></td><td>Photos (screenshots, training sessions…), optional caption</td><td>24 photos</td></tr><tr><td><strong>Testimonials</strong></td><td>The quote, its author, their role, an optional photo</td><td>12</td></tr><tr><td><strong>News</strong></td><td>Title, date, text and image; most recent first</td><td>12</td></tr><tr><td><strong>Partners</strong></td><td>The logo, the name, and the website the logo links to</td><td>24</td></tr><tr><td><strong>Contact and directions</strong></td><td>Address, phone, email, hours, a map drawn from the address</td><td>—</td></tr><tr><td><strong>Video</strong></td><td>A YouTube or Vimeo video address, and a caption</td><td>—</td></tr></tbody></table><p>The landing page holds up to 12 added sections, several of the same type if needed. Each added section has an <strong>Eyebrow</strong>, a <strong>Section title</strong> and the <strong>Show this section on the page</strong> box; <strong>Delete the section</strong> erases it with all its content, images included. The first six parts of the list appear in the menu of the top bar.</p><h3 id="editing-the-labels" tabindex="-1">Editing the labels <a class="header-anchor" href="#editing-the-labels" aria-label="Permalink to &quot;Editing the labels&quot;">​</a></h3><p>The <strong>Labels</strong> part changes the texts that belong to no part: the <strong>Create your free account</strong>, <strong>Create my account</strong> (top bar) and <strong>Compose my offer</strong> buttons, the free offer&#39;s <strong>Free</strong> badge, and the name shown in the footer after &quot;© year&quot; (edPage by default).</p><p>It also holds the footer&#39;s contact details, filled at first with edPage&#39;s:</p><ul><li><strong>Emails</strong> and <strong>Phone numbers</strong>: several values separated by commas.</li><li><strong>Legal line</strong>: the line shown after &quot;© year&quot; at the bottom of the footer. edPage&#39;s address is part of it.</li></ul><p>An empty field hides its line.</p><h3 id="sharing-and-search" tabindex="-1">Sharing and search <a class="header-anchor" href="#sharing-and-search" aria-label="Permalink to &quot;Sharing and search&quot;">​</a></h3><p>The <strong>Sharing and search</strong> part sets what Google and link previews (WhatsApp, Facebook, LinkedIn…) show of the landing page:</p><ul><li>the <strong>page title</strong>, shown in the browser tab and in search results, followed by &quot;- ERA&quot;: about sixty characters at most;</li><li>the <strong>description</strong>, the summary shown under the title: about 160 characters;</li><li>the <strong>preview image</strong>, shown when the link is shared (1200 × 630 pixels recommended). Without one, the header photo is used.</li></ul><p>Messaging apps often cache a preview for several days: a link already shared may show the old version for a while.</p><h3 id="default-texts" tabindex="-1">Default texts <a class="header-anchor" href="#default-texts" aria-label="Permalink to &quot;Default texts&quot;">​</a></h3><p>Each text is entered in French and in English. A field left empty shows its language&#39;s default text, visible greyed out in the field. You only need to fill in what you want to change. If you write in a single language, that text is reused for the other.</p><p>At first deployment, every card part and the FAQ are already filled in from the commercial proposal. Edit or delete them freely.</p><h3 id="managing-cards-and-questions" tabindex="-1">Managing cards and questions <a class="header-anchor" href="#managing-cards-and-questions" aria-label="Permalink to &quot;Managing cards and questions&quot;">​</a></h3><ul><li><strong>Add a card</strong> or <strong>Add a question</strong> opens a form; the title (or the question and answer) is required in at least one language.</li><li>The <strong>Move up</strong> and <strong>Move down</strong> arrows change the display order. For <strong>Onboarding</strong>, that order is also the step numbering on the page.</li><li><strong>Edit</strong> reopens the item; <strong>Delete</strong> removes it permanently.</li></ul><p>Each block shows its state: <strong>Shown</strong>, <strong>Hidden</strong> (unticked) or <strong>Empty, not shown</strong> (no card or question). Saving is immediate.</p><h3 id="writing-the-landing-page-s-texts" tabindex="-1">Writing the landing page&#39;s texts <a class="header-anchor" href="#writing-the-landing-page-s-texts" aria-label="Permalink to &quot;Writing the landing page&#39;s texts&quot;">​</a></h3><p>A few typing conventions shape the parts:</p><ul><li><strong>Header title</strong>: words in square brackets show in color with the <strong>Illustrated</strong> layout, e.g. &quot;From early childhood [to university].&quot; The brackets never appear on the page, whatever the layout.</li><li><strong>Free offer</strong>: the text&#39;s first paragraph introduces the offer; each following paragraph becomes a ticked step, its first sentence in bold (&quot;Step 1, ERA Admissions.&quot;). Separate paragraphs with a blank line.</li><li><strong>Levels and Modules cards</strong>: the description&#39;s first line is the headline (the module&#39;s tagline, or the pôle&#39;s introduction); each line starting with &quot;- &quot; becomes a point of the list.</li><li><strong>Illustrated module</strong> (Modules cards): the module the card presents. <strong>Academic life</strong>, <strong>Finances</strong> and <strong>Family relations</strong> have a drawing and are showcased; the other cards go under &quot;And also&quot;, where their &quot;- &quot; lines show as tags. The <strong>Badge</strong> adds a note such as &quot;New&quot;.</li><li><strong>Curricula cards</strong>: the title is the question, the description the answer, and <strong>Where it is set</strong> the table&#39;s third column.</li><li><strong>In short</strong>, <strong>Higher education</strong> and <strong>On site</strong>: the title is enough; the optional description shows under it.</li></ul><p>The <strong>Illustrated</strong> header also states, under the buttons, that online admissions are free with no time limit, and the demo length, taken from the platform&#39;s settings (60 days by default).</p><h3 id="what-the-pricing-configurator-shows" tabindex="-1">What the pricing configurator shows <a class="header-anchor" href="#what-the-pricing-configurator-shows" aria-label="Permalink to &quot;What the pricing configurator shows&quot;">​</a></h3><p>Visitors tick the modules they want; the estimate updates beside them:</p><ul><li><strong>Choose the full school licence</strong> ticks every school module at once, billed at the full-offer price (set under <strong>Pricing terms</strong>).</li><li><strong>Year 1 total</strong> adds up the licence, first-year maintenance and the chosen hosting.</li><li><strong>From year 2, per year</strong> shows what comes back each year: maintenance, plus managed hosting when it is chosen.</li><li>Document management and the additional modules stay &quot;On quote&quot;; the note under the total gives the demo&#39;s length.</li></ul><p>The default introduction quotes the maintenance rate set under <strong>Pricing terms</strong>: changing the rate updates the text.</p><h2 id="handling-contact-requests" tabindex="-1">Handling contact requests <a class="header-anchor" href="#handling-contact-requests" aria-label="Permalink to &quot;Handling contact requests&quot;">​</a></h2><p>The landing page&#39;s form sends its requests to the <strong>Contact requests</strong> screen. The number of requests still to handle shows as a badge next to its name, in the panel&#39;s menu.</p><p>Each request shows the school, the person&#39;s name, the date, the language they were browsing the landing page in, their email and phone (clickable) and their message. Requests <strong>To handle</strong> come first, newest first.</p><p>Once you have got back to the school, click <strong>Mark as handled</strong>. <strong>Mark as to handle</strong> undoes it.</p><h2 id="setting-up-a-school-s-online-payment" tabindex="-1">Setting up a school&#39;s online payment <a class="header-anchor" href="#setting-up-a-school-s-online-payment" aria-label="Permalink to &quot;Setting up a school&#39;s online payment&quot;">​</a></h2><p>A school asks for online payment from its space (<strong>Finances → Online payment</strong>). Its request reaches the panel&#39;s <strong>Online payment</strong> screen; the number of new requests shows as a badge in the menu.</p><p>Each request gives what the provider needs to open the merchant account: legal name, legal representative, RCCM, NIF, payout number for the funds, plus the name, email and phone of the person who asked. Open requests come first, oldest first.</p><ol><li>Call the school back to agree on the set-up, which is paid for and settled outside the platform. Move the request to <strong>In progress</strong> and, if useful, leave a <strong>Note for the school</strong>: the school reads it on its Online payment page.</li><li>Once paid, open the school&#39;s merchant account with the provider by hand (PayGate today).</li><li>Click <strong>Set up payment</strong> (the same screen opens from the schools list, <strong>Online payment</strong> button).</li><li>Choose the <strong>Provider</strong>, enter the account&#39;s <strong>API key</strong>, any <strong>Online payment surcharge</strong> (in %, to cover the provider&#39;s commission; cash desk payments never carry one), tick <strong>Parents can pay online</strong>, then save.</li><li>Copy the <strong>Callback address (webhook)</strong> shown and paste it in the account&#39;s dashboard at the provider, as the payment confirmation address. Without it, payments would stay &quot;Pending&quot;.</li></ol><p>On activation, the school&#39;s administrators get an email, and the request turns <strong>Activated</strong> on its own. A request not taken forward is set to <strong>Declined</strong>: the school can then send a new one.</p><p>Each school has its own merchant account: API keys are never shown again once saved (leave the field blank to keep them), and the server&#39;s configuration file is never used for a hosted school. To suspend online payment, untick <strong>Parents can pay online</strong> and save.</p>',75)])])}const u=e(s,[["render",r]]);export{p as __pageData,u as default};
